def find_frames_fixed(grid):
    """Find frames by scanning properly."""
    h, w = len(grid), len(grid[0])
    frames = []
    seen = set()

    for r in range(h):
        for c in range(w):
            val = grid[r][c]
            if val == 6:
                continue

            # Find the rectangular frame containing (r,c)
            # Scan right to find the end column
            end_c = c
            while end_c + 1 < w and grid[r][end_c + 1] == val:
                end_c += 1

            # Scan down to find the end row  
            end_r = r
            while end_r + 1 < h and grid[end_r + 1][c] == val:
                end_r += 1

            height = end_r - r + 1
            width = end_c - c + 1

            # Check if this is the top-left of the frame
            if r != 0 or c == 0:
                continue

            # Verify all four sides are the same color
            top_ok = all(grid[r][cc] == val for cc in range(c, end_c + 1))
            bottom_ok = all(grid[end_r][cc] == val for cc in range(c, end_c + 1))
            left_ok = all(grid[rr][c] == val for rr in range(r, end_r + 1))
            right_ok = all(grid[rr][end_c] == val for rr in range(r, end_r + 1))

            if not (top_ok and bottom_ok and left_ok and right_ok):
                continue

            # Check frame size
            if height < 3 or width < 3:
                continue

            # Check interior has different color (not the frame color)
            interior = True
            for dr in range(r + 1, end_r):
                for dc in range(c + 1, end_c):
                    if grid[dr][dc] == val:
                        interior = False
                        break
                if not interior:
                    break

            if interior:
                if (r, c, end_r, end_c) not in seen:
                    seen.add((r, c, end_r, end_c))
                    frames.append((r, c, end_r, end_c, height, width, val))

    return frames

