def transform(grid):
    h, w = len(grid), len(grid[0])
    result = [row[:] for row in grid]

    # Find frames: collect connected regions of same non-background color
    frames = []
    visited = set()

    for r in range(h):
        for c in range(w):
            if grid[r][c] in [0, 1, 2, 3, 4, 5, 7, 8]:  # Not 6m background
                val = grid[r][c]
                if (r, c) in visited:
                    continue

                # BFS to find connected region
                region = []
                stack = [(r, c)]
                while stack:
                    rr, cc = stack.pop()
                    if (rr, cc) in visited:
                        continue
                    visited.add((rr, cc))
                    region.append((rr, cc))
                    for dr, dc in [(-1,0), (1,0), (0,-1), (0,1)]:
                        nrr, ncc = rr + dr, cc + dc
                        if 0 <= nrr < h and 0 <= ncc < w and grid[nrr][ncc] == val and (nrr, ncc) not in visited:
                            stack.append((nrr, ncc))

                # Get bounding box
                min_r = min(p[0] for p in region)
                max_r = max(p[0] for p in region)
                min_c = min(p[1] for p in region)
                max_c = max(p[1] for p in region)

                height = max_r - min_r + 1
                width = max_c - min_c + 1

                # Check if it's a frame (hollow interior, only border is val)
                is_hollow = True
                for rr in range(min_r + 1, max_r):
                    for cc in range(min_c + 1, max_c):
                        if grid[rr][cc] == val:
                            is_hollow = False
                            break
                    if not is_hollow:
                        break

                if is_hollow and height >= 3 and width >= 3:
                    frames.append((min_r, min_c, max_r, max_c, height, width, val))

    print(f"Found {len(frames)} frames:")
    for fr in frames:
        print(f"  {fr}")

    # Fill interiors
    for sr, sc, er, ec, height, width, val in frames:
        center_r, center_c = sr + 1, sc + 1  # For 3x3: only center cell; for larger: all interior
        if height == 3 and width == 3:
            result[er-1][ec-1] = 7
        else:
            for r in range(sr + 1, er):
                for c in range(sc + 1, ec):
                    if result[r][c] == val:
                        result[r][c] = 2

    return result

