def find_frames_v2(grid):
    """Find all frames in the grid."""
    frames = []
    rows = len(grid)
    cols = len(grid[0]) if rows > 0 else 0

    for r in range(rows):
        for c in range(cols):
            if grid[r][c] == 6:
                continue

            color = grid[r][c]

            # Look for the right edge of a potential frame
            max_right = min(cols, c + 50)
            bottom_search = min(rows, r + 50)

            # Find the right edge where color continues
            for fc in range(c + 2, max_right):
                if grid[r][fc] != color:
                    continue

                # Find the bottom edge where color continues
                for fr in range(r + 2, bottom_search):
                    if grid[fr][c] != color or grid[fr][fc] != color:
                        continue

                    # Check if this forms a valid frame
                    width = fc - c + 1
                    height = fr - r + 1

                    if width < 3 or height < 3:
                        continue

                    # Verify full border
                    top_ok = True
                    for j in range(c, fc + 1):
                        if grid[r][j] != color:
                            top_ok = False
                            break

                    bottom_ok = True
                    for j in range(c, fc + 1):
                        if grid[fr][j] != color:
                            bottom_ok = False
                            break

                    left_ok = True
                    for j in range(r, fr + 1):
                        if grid[j][c] != color:
                            left_ok = False
                            break

                    right_ok = True
                    for j in range(r, fr + 1):
                        if grid[j][fc] != color:
                            right_ok = False
                            break

                    if top_ok and bottom_ok and left_ok and right_ok:
                        # Check if we already found this frame
                        found = False
                        for existing in frames:
                            if (existing['top'] == r and existing['bottom'] == fr and
                                existing['left'] == c and existing['right'] == fc and
                                existing['color'] == color):
                                found = True
                                break
                        if not found:
                            frames.append({
                                'top': r,
                                'bottom': fr,
                                'left': c,
                                'right': fc,
                                'color': color
                            })

    # Remove duplicate frames
    unique_frames = []
    for f in frames:
        is_dup = False
        for uf in unique_frames:
            if (uf['top'] == f['top'] and uf['bottom'] == f['bottom'] and
                uf['left'] == f['left'] and uf['right'] == f['right'] and
                uf['color'] == f['color']):
                is_dup = True
                break
        if not is_dup:
            unique_frames.append(f)

    return unique_frames

