def transform_grid_v2(grid):
    """Transform grid by filling maximal frames."""
    rows = len(grid)
    cols = len(grid[0]) if rows > 0 else 0

    result = [row[:] for row in grid]  # Deep copy

    # Find all maximal frames
    for r in range(rows):
        for c in range(cols):
            if grid[r][c] == 6:
                continue

            color = grid[r][c]
            max_h, max_w = 0, 0

            for h in range(3, min(rows - r + 1, 30)):
                fr = r + h - 1
                for w in range(3, min(cols - c + 1, 30)):
                    fc = c + w - 1

                    if fr >= rows or fc >= cols:
                        break

                    top_ok = all(grid[r][c+j] == color for j in range(w))
                    bottom_ok = all(grid[fr][c+j] == color for j in range(w))
                    left_ok = all(grid[r+i][c] == color for i in range(h))
                    right_ok = all(grid[r+i][fc] == color for i in range(h))

                    if top_ok and bottom_ok and left_ok and right_ok:
                        interior_empty = True
                        for i in range(1, h - 1):
                            for j in range(1, w - 1):
                                if grid[r+i][c+j] == color:
                                    interior_empty = False
                                    break
                            if not interior_empty:
                                break

                        if interior_empty and (h > max_h or (h == max_h and w > max_w)):
                            max_h, max_w = h, w

            # Fill this frame if found
            if max_h >= 3 and max_w >= 3:
                height = max_h
                width = max_w
                ir_start, ir_end = r + 1, r + max_h - 2
                ic_start, ic_end = c + 1, c + max_w - 2

                fill_val = 7 if (max_h - 1 == 1 and max_w - 1 == 1) else 2

                for i in range(ir_start, ir_end + 1):
                    for j in range(ic_start, ic_end + 1):
                        if result[i][j] == 6:
                            result[i][j] = fill_val

    return result

